# solution.py

from datetime import datetime
from collections import defaultdict
import json
import csv
import os
from abc import ABC, abstractmethod
import threading
import time
import random


# Base classes for the application
class User:
    """Represents a team member/user of the system."""
    def __init__(self, user_id, name, email):
        self.user_id = user_id
        self.name = name
        self.email = email
        self.performance = PerformanceDashboard(user_id, name)

    def __str__(self):
        return f"{self.name} ({self.email})"


class Project:
    """Represents a project within the system."""
    def __init__(self, project_id, name, start_date, end_date, description=None):
        self.project_id = project_id
        self.name = name
        self.start_date = start_date
        self.end_date = end_date
        self.description = description
        self.tasks = []
        self.messages = []

    def add_task(self, task):
        self.tasks.append(task)

    def add_message(self, message):
        self.messages.append(message)

    def get_overdue_tasks(self):
        current_date = datetime.now().date()
        return [task for task in self.tasks if task.status != "completed" and task.deadline < current_date]

    def __str__(self):
        return f"{self.name} (ID: {self.project_id})"


class Task:
    """Represents a task within a project."""
    def __init__(self, task_id, title, description, assigned_to, deadline, status="not started"):
        self.task_id = task_id
        self.title = title
        self.description = description
        self.assigned_to = assigned_to
        self.deadline = deadline
        self.status = status
        self.comments = []

    def mark_complete(self):
        self.status = "completed"

    def mark_in_progress(self):
        self.status = "in progress"

    def add_comment(self, comment, user):
        self.comments.append(f"{user.name}: {comment}")

    def __str__(self):
        return f"{self.title} (ID: {self.task_id}) - Assigned to {self.assigned_to.name}"


class Message:
    """Represents a message in the messaging system."""
    def __init__(self, message_id, sender, content, timestamp, attachment=None):
        self.message_id = message_id
        self.sender = sender
        self.content = content
        self.timestamp = timestamp
        self.attachment = attachment

    def __str__(self):
        return f"[{self.timestamp}] {self.sender.name}: {self.content}"


class PerformanceDashboard:
    """Represents a user's performance dashboard with metrics."""
    def __init__(self, user_id, name):
        self.user_id = user_id
        self.name = name
        self.completed_tasks = []
        self.feedback = []
        self.task_completion_rate = 0
        self.average_task_duration = 0

    def update_performance(self, task):
        self.completed_tasks.append(task)
        self.task_completion_rate = len(self.completed_tasks) / (len(self.completed_tasks) + len(task.user.tasks_in_progress))
        total_duration = sum((task.deadline - task.start_date).days for task in self.completed_tasks)
        self.average_task_duration = total_duration / len(self.completed_tasks) if self.completed_tasks else 0

    def add_feedback(self, feedback):
        self.feedback.append(feedback)

    def __str__(self):
        return f"{self.name}'s Dashboard - Completion Rate: {self.task_completion_rate:.2f}, Average Task Duration: {self.average_task_duration} days"


# Abstract class for report generation
class ReportGenerator(ABC):
    @abstractmethod
    def generate_report(self, data):
        pass


class CSVReportGenerator(ReportGenerator):
    """Generates reports in CSV format."""
    def generate_report(self, data, filename):
        with open(filename, mode='w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(data[0].keys())  # Write header
            for item in data:
                writer.writerow(item.values())
        return f"CSV report generated: {filename}"


class PDFReportGenerator(ReportGenerator):
    """Generates reports in PDF format (placeholder for actual PDF generation)."""
    def generate_report(self, data, filename):
        # This is a placeholder for actual PDF generation logic
        with open(filename, "w") as file:
            file.write("PDF report generation is not implemented in this version.")
        return f"PDF report generated: {filename}"


# Manager classes for handling operations
class UserManager:
    """Manages user-related operations such as creation and retrieval."""
    def __init__(self):
        self.users = {}

    def create_user(self, user_id, name, email):
        user = User(user_id, name, email)
        self.users[user_id] = user
        return user

    def get_user(self, user_id):
        return self.users.get(user_id)

    def get_all_users(self):
        return list(self.users.values())


class ProjectManager:
    """Manages project-related operations such as creation and retrieval."""
    def __init__(self):
        self.projects = {}

    def create_project(self, project_id, name, start_date, end_date, description=None):
        project = Project(project_id, name, start_date, end_date, description)
        self.projects[project_id] = project
        return project

    def get_project(self, project_id):
        return self.projects.get(project_id)

    def get_all_projects(self):
        return list(self.projects.values())

    def add_user_to_project(self, project_id, user_id):
        project = self.projects.get(project_id)
        user = UserManager().get_user(user_id)
        if project and user:
            project.add_message(f"{user.name} has been added to the project.")
            return True
        return False


class TaskManager:
    """Manages task-related operations such as creation and assignment."""
    def __init__(self):
        self.tasks = {}

    def create_task(self, task_id, title, description, assigned_to, deadline, status="not started"):
        user = UserManager().get_user(assigned_to.user_id)
        task = Task(task_id, title, description, user, deadline, status)
        project = ProjectManager().get_project(task_id[:2])  # Assuming first 2 characters identify the project
        if project:
            project.add_task(task)
        self.tasks[task_id] = task
        return task

    def update_task_status(self, task_id, new_status):
        task = self.tasks.get(task_id)
        if task:
            task.status = new_status
            task.user.performance.update_performance(task)
            return True
        return False

    def add_comment_to_task(self, task_id, comment, user):
        task = self.tasks.get(task_id)
        if task and task.assigned_to.user_id == user.user_id:
            task.add_comment(comment, user)
            return True
        return False


class MessageManager:
    """Manages messages within the system."""
    def __init__(self):
        self.messages = {}

    def send_message(self, message_id, sender, content, project_id, attachment=None):
        project = ProjectManager().get_project(project_id)
        if project:
            message = Message(message_id, sender, content, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), attachment)
            project.add_message(message)
            self.messages[message_id] = message
            return True
        return False

    def get_messages_for_project(self, project_id):
        project = ProjectManager().get_project(project_id)
        if project:
            return project.messages
        return []


class ReportManager:
    """Manages report generation for performance and project data."""
    def __init__(self):
        self.report_generator = CSVReportGenerator()

    def generate_project_report(self, project_id, format="csv"):
        project = ProjectManager().get_project(project_id)
        if not project:
            return "Project not found."
        tasks_data = [{
            "Task ID": task.task_id,
            "Title": task.title,
            "Assigned To": task.assigned_to.name,
            "Deadline": task.deadline.strftime("%Y-%m-%d"),
            "Status": task.status
        } for task in project.tasks]
        report_filename = f"{project.name}_report.{format}"
        if format == "csv":
            self.report_generator = CSVReportGenerator()
        elif format == "pdf":
            self.report_generator = PDFReportGenerator()
        return self.report_generator.generate_report(tasks_data, report_filename)

    def generate_user_performance_report(self, user_id, format="csv"):
        user = UserManager().get_user(user_id)
        if not user:
            return "User not found."
        performance_data = [{
            "User": user.name,
            "Completion Rate": f"{user.performance.task_completion_rate:.2f}",
            "Average Task Duration": f"{user.performance.average_task_duration} days"
        }]
        report_filename = f"{user.name}_performance_report.{format}"
        if format == "csv":
            self.report_generator = CSVReportGenerator()
        elif format == "pdf":
            self.report_generator = PDFReportGenerator()
        return self.report_generator.generate_report(performance_data, report_filename)


