@app.route('/projects', methods=['GET'])
@jwt_required()
def get_projects():
    current_user_id = get_jwt_identity()
    user = User.query.get(current_user_id)

    if user.role == 'User':
        # Users can only see projects where they are assigned tasks
        task_project_ids = [task.project_id for task in Task.query.filter_by(assignee_id=current_user_id).all()]
        projects = Project.query.filter(Project.id.in_(task_project_ids)).all()
    else:
        # Admins and Managers can see all projects
        projects = Project.query.all()

    return jsonify({"projects": [project.to_dict() for project in projects]}), 200

