@app.route('/projects', methods=['POST'])
@jwt_required()
def create_project():
    data = request.get_json()
    current_user_id = get_jwt_identity()
    user = User.query.get(current_user_id)

    if user.role != 'Admin' and user.role != 'Manager':
        return jsonify({"error": "Only Admins and Managers can create projects"}), 403

    name = data.get('name')
    description = data.get('description')
    start_date = data.get('start_date')
    end_date = data.get('end_date')

    if not name:
        return jsonify({"error": "Project name is required"}), 400

    try:
        start_date = datetime.datetime.strptime(start_date, '%Y-%m-%d').date() if start_date else None
        end_date = datetime.datetime.strptime(end_date, '%Y-%m-%d').date() if end_date else None
    except ValueError:
        return jsonify({"error": "Invalid date format. Use YYYY-MM-DD"}), 400

    new_project = Project(name=name, description=description, start_date=start_date, end_date=end_date, manager_id=current_user_id)
    db.session.add(new_project)
    db.session.commit()

    return jsonify({"message": "Project created successfully", "project": new_project.to_dict()}), 201

