@app.route('/projects/<int:project_id>/tasks', methods=['POST'])
@jwt_required()
def create_task(project_id):
    data = request.get_json()
    current_user_id = get_jwt_identity()

    title = data.get('title')
    description = data.get('description')
    start_date = data.get('start_date')
    due_date = data.get('due_date')
    status = data.get('status', 'Pending')
    priority = data.get('priority', 'Normal')
    assignee_id = data.get('assignee_id')

    if not title:
        return jsonify({"error": "Task title is required"}), 400

    if assignee_id:
        if not User.query.get(assignee_id):
            return jsonify({"error": "Invalid assignee ID"}), 400

    try:
        start_date = datetime.datetime.strptime(start_date, '%Y-%m-%d').date() if start_date else None
        due_date = datetime.datetime.strptime(due_date, '%Y-%m-%d').date() if due_date else None
    except ValueError:
        return jsonify({"error": "Invalid date format. Use YYYY-MM-DD"}), 400

    new_task = Task(
        title=title,
        description=description,
        start_date=start_date,
        due_date=due_date,
        status=status,
        priority=priority,
        project_id=project_id,
        assignee_id=assignee_id
    )
    db.session.add(new_task)
    db.session.commit()

    # Send email notification to assignee
    if assignee_id:
        assignee_email = User.query.get(assignee_id).email
        subject = "New Task Assigned"
        body = f"A new task titled '{title}' has been assigned to you in the project '{project_id}'."
        send_email(assignee_email, subject, body)

    return jsonify({"message": "Task created successfully", "task": new_task.to_dict()}), 201

